import { useEffect, useState } from 'react';
import { cents, dateAfter, dateTime, errorText, exportCSV, money, rpc, taipeiDate } from './lib/spa.js';
import { Empty, Field, Modal, MutationForm } from './OperationsShared.jsx';
import { StaffAccountForm, StaffArchiveForm, staffRoleNames } from './StaffPortal.jsx';
import { exportPayrollXlsx } from './lib/payroll-xlsx.js';

const moduleLabels={dashboard:'營運首頁',bookings:'預約與日程',customers:'會員與儲值金',pos:'門店 POS',team:'人員與排班',payroll:'薪資與提成',catalog:'服務・商品・庫存',reviews:'評價',reports:'經營報表',access:'角色與權限',settings:'系統設定',self:'我的薪資與績效'};
const overtimeNames={weekday:'平日延長工時',rest_day:'休息日出勤',national_holiday:'國定／特別休假',regular_holiday:'例假日出勤'};
const employmentStatusNames={active:'在職',departed:'已離職',inactive:'停用／未任職'};

export function moduleName(id){return moduleLabels[id]||id;}

export function DashboardOS({data,onNavigate,allowed,onReload}){
 const [hoursModal,setHoursModal]=useState(false);
 const cards=[
  ['bookings','預約工作台','今日 '+data.appointments+' 筆預約，'+data.pending+' 筆待確認','◎'],
  ['customers','會員中心','今日新增 '+data.new_members+' 位會員','◇'],
  ['pos','門店 POS','商品銷售、庫存與收款','▣'],
  ['team','人員系統','今日排班 '+data.staff_working+' 人','♙'],
  ['payroll','薪資系統','工時、加班、提成與結算','＄'],
  ['catalog','目錄中心','服務、商品與官網同步','▤'],
  ['reviews','評價管理','療程評價與匿名建議','☆'],
  ['reports','經營報表','營收、客單與趨勢','↗'],
  ['access','角色權限','後台角色與功能授權','⌘'],
  ['settings','系統設定','門店、床位與預約規則','⚙'],
  ['self','我的薪資與績效','堂數、評價、提成與薪資','◈']
 ].filter(([id])=>allowed(id));
 const metrics=[['今日預約',data.appointments],['已完成',data.completed],['今日在班',data.staff_working],['啟用床位',data.rooms_active]];
 if(data.revenue_cents!=null)metrics.splice(2,0,['今日實收',money(data.revenue_cents)]);
 if(data.low_stock!=null)metrics.push(['低庫存商品',data.low_stock]);
 const today=data.today_hours||{};
 const saved=async()=>{setHoursModal(false);await onReload();};
 return <>
  <section className="os-hero"><div><p className="eyebrow">BUSINESS OPERATING SYSTEM</p><h2>今天的門店，一頁掌握</h2><p className="muted">{data.date} · Asia/Taipei · 所有數字直接來自正式營運資料</p></div><button className="primary" onClick={()=>onNavigate('bookings')}>開啟今日工作台</button></section>
  <div className="grid os-metrics">{metrics.map(([label,value])=><article className="card" key={label}><p className="muted">{label}</p><div className="metric">{value}</div></article>)}</div>
  <section className={`card os-today-hours ${today.is_open?'is-open':'is-closed'}`}><div><p className="eyebrow">TODAY · LIVE</p><h2>{today.is_open?'今日營業':'今日休假'}</h2><p>{today.is_open?`${minuteLabel(today.opening_minute)}–${minuteLabel(today.closing_minute)}`:'官網今日不提供新預約時段'}{today.note?` · ${today.note}`:''}</p><p className="muted">{today.source==='override'?'今日特殊設定，已即時同步官網與預約空檔。':'目前使用每週營業時間。'}</p></div>{allowed('settings')&&<button className="primary" onClick={()=>setHoursModal(true)}>設定今日營業／休假</button>}</section>
  <h2>系統直通車</h2><div className="os-launcher">{cards.map(([id,title,desc,icon])=><button key={id} onClick={()=>onNavigate(id)}><span className="os-icon">{icon}</span><span><strong>{title}</strong><small>{desc}</small></span></button>)}</div>
  <div className="split os-dashboard-lower"><section className="card"><h2>接下來的預約</h2>{!data.next_appointments.length&&<Empty>今天目前沒有有效預約。</Empty>}{data.next_appointments.map(row=><button className="os-list-button" key={row.id} onClick={()=>onNavigate('bookings')}><span><strong>{dateTime(row.starts_at)}</strong><small>{row.customer_name} · {row.service_name}</small></span><span>{row.staff_name}<br/><small>{row.resource_name}</small></span></button>)}</section><section className="card"><h2>今日提醒</h2><p>{data.pending?`還有 ${data.pending} 筆預約等待確認。`:'待確認預約已清空。'}</p><p>{data.cancelled?`今日取消或未到 ${data.cancelled} 筆。`:'今日沒有取消或未到。'}</p>{data.low_stock!=null&&<p>{data.low_stock?`${data.low_stock} 項商品已達低庫存門檻。`:'目前沒有低庫存提醒。'}</p>}<p>目前啟用 {data.rooms_active} 個服務床位。</p></section></div>
  {hoursModal&&<Modal title="今日營業狀態" onClose={()=>setHoursModal(false)}><DayOverrideForm date={data.date} value={today} saved={saved}/></Modal>}
 </>;
}

export function TeamOS({data,catalog,canManage,canAccounts,onReload}){
 const [modal,setModal]=useState(null),[query,setQuery]=useState(''),[status,setStatus]=useState('employment'),[archived,setArchived]=useState(false);
 const rows=data.staff.filter(s=>{const current=s.employment_status||(s.active?'active':'inactive'),statusMatch=status==='all'||(status==='employment'&&['active','departed'].includes(current))||current===status;return (archived||!s.archived_at)&&statusMatch&&`${s.name} ${s.phone} ${s.title} ${s.employment_type_name}`.toLowerCase().includes(query.toLowerCase());});
 const roles=data.role_profiles||[];
 const saved=async()=>{setModal(null);await onReload();};
 return <>
  <div className="os-page-title"><div><h2>人員與排班</h2><p className="muted">人事資料、職稱、服務能力、帳號與歷史績效都綁定同一位人員；薪資與提成統一到「薪資與提成」依職稱和聘僱類型設定。</p></div>{canManage&&<button className="primary" onClick={()=>setModal({kind:'profile',row:null})}>新增人員</button>}</div>
  <div className="toolbar"><input aria-label="搜尋人員" placeholder="搜尋姓名、手機、職稱" value={query} onChange={e=>setQuery(e.target.value)}/><select aria-label="任職狀態" value={status} onChange={e=>setStatus(e.target.value)}><option value="employment">在職與已離職</option>{Object.entries(employmentStatusNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}<option value="all">全部（含停用／未任職）</option></select><label className="auto-refresh"><input type="checkbox" checked={archived} onChange={e=>setArchived(e.target.checked)}/>顯示已封存</label></div>
  {!rows.length&&<Empty/>}<div className="grid os-team-grid">{rows.map(s=>{const workStatus=s.employment_status||(s.active?'active':'inactive'),isCurrent=workStatus==='active',account=data.accounts.find(a=>a.staff_id===s.id),shifts=data.shifts.filter(x=>x.staff_id===s.id),daily=(data.daily_shifts||[]).filter(x=>x.staff_id===s.id&&x.business_date>=taipeiDate()).slice(0,3);return <article className={`card ${workStatus==='departed'?'staff-departed':''}`} key={s.id}><div className="os-person"><span className="os-avatar">{s.name.slice(0,1)}</span><div><h3>{s.name}</h3><p>{s.job_title_name||s.title} · {s.employment_type_name||'未設定'}</p></div></div><div className="row"><span className="badge">{employmentStatusNames[workStatus]}</span><span className="badge">{isCurrent&&s.is_bookable&&!s.archived_at?'可接單':'不接單'}</span><span className="badge">{isCurrent&&s.website_visible?'官網顯示':'官網隱藏'}</span></div>{workStatus==='departed'&&<p className="staff-departure"><strong>離職日：{s.departed_on}</strong>{s.departure_reason&&<> · {s.departure_reason}</>}</p>}<p>{s.phone||'未填手機'} · {s.email||'未填電子郵件'}</p><p className="muted">薪資規則：{s.job_title_name||s.title} × {s.employment_type_name||'未設定'}，請至「薪資與提成」維護。</p>{isCurrent&&<><div className="os-shift-summary">{shifts.length?shifts.sort((a,b)=>a.weekday-b.weekday).map(sh=><small key={sh.id}>週{'日一二三四五六'[sh.weekday]} {minuteLabel(sh.start_minute)}–{minuteLabel(sh.end_minute)}</small>):<small>尚未設定每週排班</small>}</div>{daily.length>0&&<div className="os-daily-summary">{daily.map(sh=><small key={sh.id}>{sh.business_date} · {sh.is_working?`${minuteLabel(sh.start_minute)}–${minuteLabel(sh.end_minute)}`:'休班'}{sh.note?` · ${sh.note}`:''}</small>)}</div>}</>}<p className="muted">登入：{account?`${account.username||'未命名'} · ${roles.find(r=>r.code===account.role)?.name||staffRoleNames[account.role]||account.role} · ${account.active?'啟用':'停用'}`:'尚未建立'}</p>{canManage&&<div className="actions"><button onClick={()=>setModal({kind:'profile',row:s})}>編輯檔案</button>{isCurrent&&<><button onClick={()=>setModal({kind:'daily',row:s})}>每日排班</button><button onClick={()=>setModal({kind:'shift',row:s})}>每週設定</button><button onClick={()=>setModal({kind:'off',row:s})}>休假／封鎖</button>{canAccounts&&account?.role!=='owner'&&<button onClick={()=>setModal({kind:'account',row:s,account})}>登入帳號</button>}</>}{canAccounts&&account?.role!=='owner'&&<button onClick={()=>setModal({kind:'archive',row:s})}>{s.archived_at?'恢復':'封存'}</button>}</div>}</article>})}</div>
  <h2>每日排班</h2><p className="muted">指定日期排班會覆蓋每週設定，並即時控制該技師在前台是否有可預約時段。</p>{!(data.daily_shifts||[]).filter(x=>x.business_date>=taipeiDate()).length&&<Empty>尚未建立未來每日排班，系統目前使用每週設定。</Empty>}<div className="grid">{(data.daily_shifts||[]).filter(x=>x.business_date>=taipeiDate()).slice(0,28).map(sh=><article className="card" key={sh.id}><h3>{data.staff.find(s=>s.id===sh.staff_id)?.name||'已封存人員'} · {sh.business_date}</h3><p>{sh.is_working?`${minuteLabel(sh.start_minute)}–${minuteLabel(sh.end_minute)}`:'休班'}</p>{sh.note&&<p className="muted">{sh.note}</p>}{canManage&&<div className="actions"><button onClick={()=>setModal({kind:'daily',row:data.staff.find(s=>s.id===sh.staff_id),shift:sh})}>修改</button><button className="danger" onClick={()=>setModal({kind:'daily-delete',row:sh})}>恢復每週設定</button></div>}</article>)}</div>
  <h2>休假與特殊封鎖</h2><p className="muted">這些時段會立即從官網可預約時段排除；可用於請假、休息、訓練或特殊日期停班。</p>{!data.time_off.length&&<Empty>目前沒有休假或封鎖時段。</Empty>}<div className="grid">{data.time_off.map(t=><article className="card" key={t.id}><h3>{data.staff.find(s=>s.id===t.staff_id)?.name||'已封存人員'}</h3><p>{dateTime(t.starts_at)} ～ {dateTime(t.ends_at)}</p><p className="muted">{t.reason}</p>{canManage&&<button className="danger" onClick={()=>setModal({kind:'off-delete',row:t})}>刪除</button>}</article>)}</div>
  {modal&&<Modal title={{profile:modal.row?'編輯人員':'新增人員',account:'登入帳號與角色',archive:modal.row?.archived_at?'恢復人員':'封存人員',shift:'設定每週排班',daily:'設定每日排班','daily-delete':'恢復每週排班',off:'新增休假／封鎖時段','off-delete':'刪除休假／封鎖時段'}[modal.kind]} onClose={()=>setModal(null)}>{modal.kind==='profile'&&<StaffProfileForm row={modal.row} data={data} catalog={catalog} saved={saved}/>} {modal.kind==='account'&&<StaffAccountForm row={modal.row} account={modal.account} roles={roles} saved={saved}/>} {modal.kind==='archive'&&<StaffArchiveForm row={modal.row} saved={saved}/>} {modal.kind==='shift'&&<ShiftEditor row={modal.row} shifts={data.shifts.filter(x=>x.staff_id===modal.row.id)} saved={saved}/>} {modal.kind==='daily'&&<DailyShiftEditor row={modal.row} shift={modal.shift} saved={saved}/>} {modal.kind==='daily-delete'&&<MutationForm action={()=>rpc('spa_daily_shift_delete',{p_staff:modal.row.staff_id,p_date:modal.row.business_date})} onSaved={saved} submit="恢復每週設定"><p>{modal.row.business_date} 的每日覆蓋設定會刪除，前台將重新讀取該星期的預設排班。</p></MutationForm>} {modal.kind==='off'&&<TimeOffEditor row={modal.row} saved={saved}/>} {modal.kind==='off-delete'&&<MutationForm action={()=>rpc('spa_time_off_delete',{p_id:modal.row.id})} onSaved={saved} submit="確認刪除"><p>{modal.row.reason}</p><p className="alert">刪除後，這段時間將重新開放供預約引擎判斷。</p></MutationForm>}</Modal>}
 </>;
}

function StaffProfileForm({row,data,catalog,saved}){
 const firstTitle=data.job_titles.find(x=>x.active);
 const initial=row?{...row,employment_status:row.employment_status||(row.active?'active':'inactive'),departed_on:row.departed_on||'',departure_reason:row.departure_reason||''}:{name:'',name_en:'',title:firstTitle?.name||'調理師',specialty:'',bio:'',phone:'',email:'',address:'',birth_date:'',hire_date:taipeiDate(),employment_type_code:'full_time',job_title_id:firstTitle?.id||'',active:true,is_bookable:true,website_visible:true,photo_url:'',employment_status:'active',departed_on:'',departure_reason:''};
 const [f,setF]=useState(initial),[services,setServices]=useState(row?catalog.skills.filter(x=>x.staff_id===row.id&&x.enabled!==false).map(x=>x.service_id):catalog.services.map(x=>x.id));
 const set=(key,value)=>setF(v=>({...v,[key]:value}));
 const payload={...f,id:row?.id||'',services};
 return <MutationForm action={()=>rpc('spa_staff_profile_save_v2',{p_payload:payload})} onSaved={saved}><div className="form-grid"><Field label="姓名"><input required maxLength="80" value={f.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="英文姓名"><input maxLength="80" value={f.name_en||''} onChange={e=>set('name_en',e.target.value)}/></Field><Field label="按摩師職稱"><select required value={f.job_title_id||''} onChange={e=>{const title=data.job_titles.find(x=>x.id===e.target.value);setF(v=>({...v,job_title_id:e.target.value,title:title?.name||v.title}));}}>{data.job_titles.filter(x=>x.active).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="聘僱類型"><select value={f.employment_type_code||'full_time'} onChange={e=>set('employment_type_code',e.target.value)}>{data.employment_types.filter(x=>x.active).map(x=><option key={x.code} value={x.code}>{x.name}</option>)}</select></Field><Field label="手機"><input type="tel" value={f.phone||''} onChange={e=>set('phone',e.target.value)}/></Field><Field label="電子郵件"><input type="email" value={f.email||''} onChange={e=>set('email',e.target.value)}/></Field><Field label="生日"><input type="date" value={f.birth_date||''} onChange={e=>set('birth_date',e.target.value)}/></Field><Field label="到職日"><input type="date" value={f.hire_date||''} onChange={e=>set('hire_date',e.target.value)}/></Field><Field label="任職狀態"><select value={f.employment_status} onChange={e=>{const value=e.target.value;setF(v=>({...v,employment_status:value,active:value==='active',departed_on:value==='departed'?(v.departed_on||taipeiDate()):'',departure_reason:value==='departed'?v.departure_reason:'',is_bookable:value==='active'?v.is_bookable:false,website_visible:value==='active'?v.website_visible:false}));}}>{Object.entries(employmentStatusNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></Field>{f.employment_status==='departed'&&<><Field label="離職日期"><input type="date" required value={f.departed_on} onChange={e=>set('departed_on',e.target.value)}/></Field><Field wide label="離職原因"><textarea required maxLength="1000" value={f.departure_reason} onChange={e=>set('departure_reason',e.target.value)}/></Field></>}<Field label="頭像網址"><input type="url" value={f.photo_url||''} onChange={e=>set('photo_url',e.target.value)}/></Field><Field wide label="地址"><input value={f.address||''} onChange={e=>set('address',e.target.value)}/></Field><Field label="專長"><input value={f.specialty||''} onChange={e=>set('specialty',e.target.value)}/></Field><Field label="預約接單"><select disabled={f.employment_status!=='active'} value={String(f.is_bookable)} onChange={e=>set('is_bookable',e.target.value==='true')}><option value="true">可接單</option><option value="false">不接單</option></select></Field><Field label="官網顯示"><select disabled={f.employment_status!=='active'} value={String(f.website_visible)} onChange={e=>set('website_visible',e.target.value==='true')}><option value="true">顯示</option><option value="false">隱藏</option></select></Field><Field wide label="人員介紹"><textarea maxLength="2000" value={f.bio||''} onChange={e=>set('bio',e.target.value)}/></Field><Field wide label="可提供療程"><div className="os-check-grid">{catalog.services.map(s=><label key={s.id}><input type="checkbox" checked={services.includes(s.id)} onChange={e=>setServices(e.target.checked?[...services,s.id]:services.filter(id=>id!==s.id))}/>{s.name}</label>)}</div></Field></div><p className="muted">薪資、療程提成、商品提成與指定客獎金，會依「職稱 × 聘僱類型」自動套用；人事頁不再重複設定。標記離職會停止接單並停用後台帳號，但保留全部歷史。</p></MutationForm>;
}

function minuteLabel(n){return `${n>=1440?'翌日 ':''}${String(Math.floor(n/60)%24).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function ShiftEditor({row,shifts,saved}){
 const [day,setDay]=useState(String(shifts[0]?.weekday??1)),current=shifts.find(x=>String(x.weekday)===day);
 const [start,setStart]=useState(current?.start_minute??600),[end,setEnd]=useState(current?.end_minute??1560);
 useEffect(()=>{const value=shifts.find(x=>String(x.weekday)===day);setStart(value?.start_minute??600);setEnd(value?.end_minute??1560);},[day]);
 const choices=Array.from({length:97},(_,i)=>i*30);
 return <MutationForm action={()=>rpc('spa_shift_save',{p_staff:row.id,p_weekday:Number(day),p_start:Number(start),p_end:Number(end)})} onSaved={saved}><p>{row.name} · 同一星期幾再次儲存會更新原排班。</p><div className="form-grid"><Field label="星期"><select value={day} onChange={e=>setDay(e.target.value)}>{[0,1,2,3,4,5,6].map(d=><option key={d} value={d}>週{'日一二三四五六'[d]}</option>)}</select></Field><Field label="開始"><select value={start} onChange={e=>setStart(Number(e.target.value))}>{choices.slice(0,49).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field><Field label="結束（可至翌日）"><select value={end} onChange={e=>setEnd(Number(e.target.value))}>{choices.filter(n=>n>start).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field></div><p className="muted">休息時間可在「休假／封鎖」建立；修改排班會立即影響官網空檔，但不會取消既有預約。</p></MutationForm>;
}
function DailyShiftEditor({row,shift,saved}){
 const [date,setDate]=useState(shift?.business_date||taipeiDate()),[working,setWorking]=useState(shift?.is_working??true),[start,setStart]=useState(shift?.start_minute??600),[end,setEnd]=useState(shift?.end_minute??1560),[note,setNote]=useState(shift?.note||'');
 const choices=Array.from({length:97},(_,i)=>i*30);
 return <MutationForm action={()=>rpc('spa_daily_shift_save',{p_staff:row.id,p_date:date,p_is_working:working,p_start:Number(start),p_end:Number(end),p_note:note})} onSaved={saved} submit="儲存每日排班"><p><strong>{row.name}</strong> · 此日期設定優先於每週設定，並立即聯動前台可預約時段。</p><div className="form-grid"><Field label="日期"><input type="date" required min={taipeiDate()} disabled={!!shift} value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="狀態"><select value={String(working)} onChange={e=>setWorking(e.target.value==='true')}><option value="true">上班／開放預約</option><option value="false">休班／不開放預約</option></select></Field>{working&&<><Field label="開始"><select value={start} onChange={e=>{const n=Number(e.target.value);setStart(n);if(n>=end)setEnd(Math.min(2880,n+60));}}>{choices.slice(0,49).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field><Field label="結束（可至翌日）"><select value={end} onChange={e=>setEnd(Number(e.target.value))}>{choices.filter(n=>n>start).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field></>}<Field wide label="備註"><input maxLength={500} value={note} onChange={e=>setNote(e.target.value)} placeholder={working?'例如：暫時早班':'例如：排休'}/></Field></div><p className="muted">若新排班會把既有預約排除在外，系統會阻止儲存；請先在預約頁更換或改期。</p></MutationForm>;
}
function TimeOffEditor({row,saved}){const [start,setStart]=useState(''),[end,setEnd]=useState(''),[reason,setReason]=useState('');return <MutationForm action={()=>rpc('spa_time_off_save',{p_staff:row.id,p_start:`${start}:00+08:00`,p_end:`${end}:00+08:00`,p_reason:reason})} onSaved={saved}><p>{row.name} · 台灣時間</p><div className="form-grid"><Field label="開始"><input type="datetime-local" required value={start} onChange={e=>setStart(e.target.value)}/></Field><Field label="結束"><input type="datetime-local" required value={end} onChange={e=>setEnd(e.target.value)}/></Field><Field wide label="原因"><input required maxLength="500" value={reason} onChange={e=>setReason(e.target.value)}/></Field></div></MutationForm>}

export function CatalogOS({data,canManage,onReload}){
 const [section,setSection]=useState('services'),[modal,setModal]=useState(null),[selected,setSelected]=useState([]),[query,setQuery]=useState(''),[showArchived,setShowArchived]=useState(false);
 const rows=(section==='services'?data.services:data.products).filter(x=>(showArchived||x.status!=='archived')&&`${x.name} ${x.code||x.sku||''}`.toLowerCase().includes(query.toLowerCase()));
 const saved=async()=>{setModal(null);setSelected([]);await onReload();};
 const bulk=async action=>{if(!selected.length)return;await rpc('spa_catalog_bulk',{p_kind:section==='services'?'service':'product',p_ids:selected,p_action:action,p_value:null});setSelected([]);await onReload();};
 return <><div className="os-page-title"><div><h2>服務・商品・庫存</h2><p className="muted">官網、預約、POS 與薪資共用同一份主資料。畫面金額一律使用新台幣「元」，儲存時由系統換算。</p></div>{canManage&&<button className="primary" onClick={()=>setModal({kind:section==='services'?'service':'product',row:null})}>新增{section==='services'?'服務':'商品'}</button>}</div><nav><button className={section==='services'?'active':''} onClick={()=>{setSection('services');setSelected([]);}}>服務項目</button><button className={section==='products'?'active':''} onClick={()=>{setSection('products');setSelected([]);}}>商品與庫存</button></nav><div className="toolbar"><input aria-label="搜尋目錄" placeholder="搜尋名稱、代碼或 SKU" value={query} onChange={e=>setQuery(e.target.value)}/><label className="auto-refresh"><input type="checkbox" checked={showArchived} onChange={e=>setShowArchived(e.target.checked)}/>顯示已封存</label>{canManage&&selected.length>0&&<><span className="badge">已選 {selected.length}</span><button onClick={()=>bulk('publish')}>上架</button><button onClick={()=>bulk('hide')}>隱藏</button><button className="danger" onClick={()=>bulk('archive')}>封存</button></>}</div>{!rows.length&&<Empty/>}<div className="table-wrap"><table><thead><tr>{canManage&&<th>選取</th>}<th>名稱</th><th>{section==='services'?'時間':'SKU'}</th><th>售價</th><th>{section==='services'?'預約／官網':'庫存'}</th><th>狀態</th>{canManage&&<th>操作</th>}</tr></thead><tbody>{rows.map(row=><tr key={row.id}>{canManage&&<td><input aria-label={`選取${row.name}`} type="checkbox" checked={selected.includes(row.id)} onChange={e=>setSelected(e.target.checked?[...selected,row.id]:selected.filter(id=>id!==row.id))}/></td>}<td><strong>{row.name}</strong><small className="table-sub">{row.category_name||'未分類'}{row.name_en?` · ${row.name_en}`:''}</small></td><td>{section==='services'?`${row.duration_minutes} 分鐘＋${row.buffer_minutes} 分鐘緩衝`:row.sku}</td><td>{money(row.price_cents)}</td><td>{section==='services'?`${row.online_booking_enabled?'可預約':'不預約'}／${row.website_visible?'顯示':'隱藏'}`:<><span className={Number(row.inventory)<=Number(row.low_stock_threshold)?'alert-inline':''}>{row.inventory}</span> {row.unit_label||'件'}</>}</td><td><span className="badge">{{active:'上架',draft:'草稿',archived:'封存'}[row.status]}</span></td>{canManage&&<td><div className="actions"><button onClick={()=>setModal({kind:section==='services'?'service':'product',row})}>編輯</button>{section==='products'&&<button onClick={()=>setModal({kind:'inventory',row})}>調庫存</button>}<button className="danger" onClick={()=>setModal({kind:'delete',row,itemKind:section==='services'?'service':'product'})}>刪除</button></div></td>}</tr>)}</tbody></table></div>{modal&&<Modal title={modal.kind==='inventory'?'庫存調整':modal.kind==='delete'?`刪除${modal.itemKind==='service'?'服務':'商品'}`:`${modal.row?'編輯':'新增'}${modal.kind==='service'?'服務':'商品'}`} onClose={()=>setModal(null)}>{modal.kind==='service'&&<ServiceEditor row={modal.row} categories={data.service_categories} saved={saved}/>} {modal.kind==='product'&&<ProductEditor row={modal.row} categories={data.product_categories} saved={saved}/>} {modal.kind==='inventory'&&<InventoryEditor row={modal.row} saved={saved}/>} {modal.kind==='delete'&&<CatalogDelete row={modal.row} kind={modal.itemKind} saved={saved}/>}</Modal>}</>;
}

function ServiceEditor({row,categories,saved}){
 const durationCategories=categories.filter(c=>c.active&&/^duration_(45|60|90|120)$/.test(c.code)).sort((a,b)=>a.display_order-b.display_order);
 const defaultCategory=durationCategories[0];
 const [f,setF]=useState(row?{...row,price:Number(row.price_cents)/100,member_price:row.member_price_cents==null?'':Number(row.member_price_cents)/100}:{code:'',name:'',name_en:'',category_id:defaultCategory?.id||'',description:'',description_en:'',duration_minutes:Number(defaultCategory?.code?.replace('duration_',''))||45,buffer_minutes:15,price:0,member_price:'',image_url:'',status:'draft',online_booking_enabled:false,website_visible:false,display_order:0,website_content:{}});const set=(key,value)=>setF(v=>({...v,[key]:value}));
 const setCategory=id=>{const category=durationCategories.find(item=>item.id===id);setF(value=>({...value,category_id:id,duration_minutes:Number(category?.code.replace('duration_',''))||value.duration_minutes}));};
 const payload={...f,id:row?.id||'',price_cents:cents(f.price),member_price_cents:f.member_price===''?'':cents(f.member_price),duration_minutes:Number(f.duration_minutes),buffer_minutes:Number(f.buffer_minutes),display_order:Number(f.display_order)};
 return <MutationForm action={()=>rpc('spa_service_save_v2',{p_payload:payload})} onSaved={saved}><div className="form-grid"><Field label="中文名稱"><input required value={f.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="英文名稱"><input value={f.name_en||''} onChange={e=>set('name_en',e.target.value)}/></Field><Field label="代碼"><input disabled={!!row} placeholder="留空自動建立" value={f.code||''} onChange={e=>set('code',e.target.value)}/></Field><Field label="時間分類"><select required value={f.category_id||''} onChange={e=>setCategory(e.target.value)}>{durationCategories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="療程時間（由分類決定）"><input readOnly value={`${f.duration_minutes} 分鐘`}/></Field><Field label="清潔緩衝（分鐘）"><input required type="number" min="0" max="180" step="1" value={f.buffer_minutes} onChange={e=>set('buffer_minutes',e.target.value)}/></Field><Field label="售價 NT$（元）"><input required type="number" min="0" step="0.01" value={f.price} onChange={e=>set('price',e.target.value)}/></Field><Field label="會員價 NT$（元）"><input type="number" min="0" step="0.01" value={f.member_price} onChange={e=>set('member_price',e.target.value)}/></Field><Field label="狀態"><select value={f.status} onChange={e=>set('status',e.target.value)}><option value="draft">草稿</option><option value="active">上架</option><option value="archived">封存</option></select></Field><Field label="分類內排序"><input type="number" step="1" value={f.display_order} onChange={e=>set('display_order',e.target.value)}/></Field><Field label="線上預約"><select value={String(f.online_booking_enabled)} onChange={e=>set('online_booking_enabled',e.target.value==='true')}><option value="true">開放</option><option value="false">關閉</option></select></Field><Field label="官網顯示"><select value={String(f.website_visible)} onChange={e=>set('website_visible',e.target.value==='true')}><option value="true">顯示</option><option value="false">隱藏</option></select></Field><Field wide label="中文介紹"><textarea value={f.description||''} onChange={e=>set('description',e.target.value)}/></Field><Field wide label="英文介紹"><textarea value={f.description_en||''} onChange={e=>set('description_en',e.target.value)}/></Field><Field wide label="圖片網址"><input type="url" value={f.image_url||''} onChange={e=>set('image_url',e.target.value)}/></Field></div><WebsiteCardsEditor value={f.website_content||{}} onChange={value=>set('website_content',value)} service={f}/><p className="muted">服務必須屬於 45、60、90 或 120 分鐘分類；分類會同步決定療程時間與前台位置。歷史預約保留成交快照，封存只影響新預約。</p></MutationForm>;
}

function WebsiteCardsEditor({value,onChange,service}){
 const languages=[['zh','中文'],['en','英文']];
 const cards=lang=>Array.isArray(value?.[lang])?value[lang]:[];
 const replace=(lang,next)=>onChange({...value,[lang]:next});
 const update=(lang,index,key,next)=>replace(lang,cards(lang).map((card,i)=>i===index?{...card,[key]:next}:card));
 const add=lang=>replace(lang,[...cards(lang),{stamp:'',name:'',sub:'',steps:[]}]);
 const remove=(lang,index)=>replace(lang,cards(lang).filter((_,i)=>i!==index));
 return <section className="catalog-presentation-editor"><div><h3>官網療程卡片</h3><p className="muted">沒有自訂卡片時，官網會依療程名稱、介紹與時間自動生成統一樣式；需要多個方子時可在這裡新增。</p></div>{languages.map(([lang,label])=><details key={lang} open={lang==='zh'}><summary>{label}卡片 <span className="badge">{cards(lang).length||'自動'}</span></summary><div className="catalog-presentation-list">{cards(lang).map((card,index)=><article className="card" key={index}><div className="catalog-presentation-title"><strong>{label}卡片 {index+1}</strong><button type="button" className="danger" onClick={()=>remove(lang,index)}>刪除卡片</button></div><div className="form-grid"><Field label="章字（1–2 字）"><input maxLength="2" value={card.stamp||''} onChange={e=>update(lang,index,'stamp',e.target.value)} placeholder="留空自動產生"/></Field><Field label="卡片標題"><input required value={card.name||''} onChange={e=>update(lang,index,'name',e.target.value)}/></Field><Field wide label="卡片副標"><input value={card.sub||''} onChange={e=>update(lang,index,'sub',e.target.value)}/></Field><Field wide label="療程步驟（每行一項）"><textarea value={(card.steps||[]).join('\n')} onChange={e=>update(lang,index,'steps',e.target.value.split('\n'))} placeholder={lang==='zh'?'頭肩頸按摩\n頭皮清潔\n手技收尾':'Head and neck massage\nScalp cleanse\nFinishing massage'}/></Field></div></article>)}<button type="button" onClick={()=>add(lang)}>＋ 新增{label}卡片</button>{!cards(lang).length&&<p className="muted">目前使用自動卡片：{lang==='zh'?(service.description||service.name||'尚未輸入內容'):(service.description_en||service.name_en||service.name||'No content yet')}</p>}</div></details>)}</section>;
}

function ProductEditor({row,categories,saved}){
 const [f,setF]=useState(row?{...row,price:Number(row.price_cents)/100,cost:row.cost_cents==null?'':Number(row.cost_cents)/100}:{sku:'',name:'',name_en:'',category_id:'',description:'',description_en:'',image_url:'',price:0,cost:'',barcode:'',unit_label:'件',unit_label_en:'',low_stock_threshold:2,status:'draft',website_visible:false,store_visible:false,display_order:0});const set=(key,value)=>setF(v=>({...v,[key]:value}));
 const payload={...f,id:row?.id||'',price_cents:cents(f.price),cost_cents:f.cost===''?'':cents(f.cost),low_stock_threshold:Number(f.low_stock_threshold),display_order:Number(f.display_order)};
 return <MutationForm action={()=>rpc('spa_product_save',{p_payload:payload})} onSaved={saved}><div className="form-grid"><Field label="SKU"><input required value={f.sku} onChange={e=>set('sku',e.target.value)}/></Field><Field label="條碼"><input value={f.barcode||''} onChange={e=>set('barcode',e.target.value)}/></Field><Field label="中文名稱"><input required value={f.name} onChange={e=>set('name',e.target.value)}/></Field><Field label="英文名稱"><input value={f.name_en||''} onChange={e=>set('name_en',e.target.value)}/></Field><Field label="分類"><select value={f.category_id||''} onChange={e=>set('category_id',e.target.value)}><option value="">未分類</option>{categories.filter(c=>c.active).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><Field label="庫存單位（例：盒、瓶、件）"><input required value={f.unit_label||''} onChange={e=>set('unit_label',e.target.value)}/></Field><Field label="售價 NT$（元）"><input required type="number" min="0" step="0.01" value={f.price} onChange={e=>set('price',e.target.value)}/></Field><Field label="成本 NT$（元）"><input type="number" min="0" step="0.01" value={f.cost} onChange={e=>set('cost',e.target.value)}/></Field><Field label={`低庫存提醒（${f.unit_label||'庫存單位'}）`}><input type="number" min="0" step="1" value={f.low_stock_threshold} onChange={e=>set('low_stock_threshold',e.target.value)}/></Field><Field label="排序"><input type="number" step="1" value={f.display_order} onChange={e=>set('display_order',e.target.value)}/></Field><Field label="狀態"><select value={f.status} onChange={e=>set('status',e.target.value)}><option value="draft">草稿</option><option value="active">上架</option><option value="archived">封存</option></select></Field><Field label="官網／商店"><div className="row"><label><input type="checkbox" checked={f.website_visible} onChange={e=>set('website_visible',e.target.checked)}/>官網顯示</label><label><input type="checkbox" checked={f.store_visible} onChange={e=>set('store_visible',e.target.checked)}/>商店顯示</label></div></Field><Field wide label="中文介紹"><textarea value={f.description||''} onChange={e=>set('description',e.target.value)}/></Field><Field wide label="英文介紹"><textarea value={f.description_en||''} onChange={e=>set('description_en',e.target.value)}/></Field><Field wide label="圖片網址"><input type="url" value={f.image_url||''} onChange={e=>set('image_url',e.target.value)}/></Field></div><p className="muted">售價與成本輸入新台幣元；庫存與提醒門檻使用上方自訂單位。</p></MutationForm>;
}
function CatalogDelete({row,kind,saved}){const [confirmation,setConfirmation]=useState('');return <MutationForm action={()=>rpc('spa_catalog_delete',{p_kind:kind,p_id:row.id,p_confirmation:confirmation})} onSaved={saved} submit="確認刪除"><p><strong>{row.name}</strong></p><p className="alert">若已有預約、套票或訂單歷史，系統會安全封存並保留帳務；沒有歷史才會永久刪除。</p><Field label="輸入 DELETE 確認"><input required autoComplete="off" value={confirmation} onChange={e=>setConfirmation(e.target.value)} placeholder="DELETE"/></Field></MutationForm>}
function InventoryEditor({row,saved}){const [quantity,setQuantity]=useState(''),[reason,setReason]=useState('');return <MutationForm action={()=>rpc('spa_inventory_adjustment',{p_product:row.id,p_delta:Number(quantity),p_reason:reason})} onSaved={saved}><p>{row.name} · 目前庫存 {row.inventory}</p><Field label="調整數量（增加為正數，扣除為負數）"><input required type="number" step="1" value={quantity} onChange={e=>setQuantity(e.target.value)}/></Field><Field label="原因"><textarea required maxLength="500" value={reason} onChange={e=>setReason(e.target.value)}/></Field></MutationForm>}

export function PayrollOS({data,staff,from,to,canManage,onReload}){
 const activeRuleId=data.rules.find(x=>x.status==='active')?.id||data.rules[0]?.id||'';
 const [tab,setTab]=useState('summary'),[modal,setModal]=useState(null),[rule,setRule]=useState(activeRuleId),[preview,setPreview]=useState(data.preview),[previewError,setPreviewError]=useState('');
 useEffect(()=>{setPreview(data.preview);},[data.preview]);
 useEffect(()=>{setRule(activeRuleId);},[activeRuleId]);
 useEffect(()=>{if(!rule)return;let live=true;setPreviewError('');rpc('spa_payroll_preview',{p_from:from,p_to:to,p_rule:rule}).then(rows=>{if(live)setPreview(rows);}).catch(error=>{if(live)setPreviewError(error.message||'薪資試算載入失敗');});return()=>{live=false;};},[rule,from,to]);
 const selected=data.rules.find(x=>x.id===rule),total=preview.reduce((sum,row)=>sum+Number(row.total_cents),0),serviceRevenue=preview.reduce((sum,row)=>sum+Number(row.service_sales_cents),0),commissionTotal=preview.reduce((sum,row)=>sum+Number(row.service_commission_cents)+Number(row.product_commission_cents)+Number(row.designated_bonus_cents),0),settled=preview.reduce((n,row)=>n+Number(row.service_count),0),unsettled=preview.reduce((n,row)=>n+Number(row.unsettled_completed_count),0),warningCount=preview.filter(row=>row.commission_warning||row.overtime_warning).length;
 const saved=async()=>{setModal(null);await onReload();};
 const exportRows=()=>exportCSV(`薪資試算_${from}_${to}.csv`,preview.map(r=>({員工:r.employee,任職狀態:employmentStatusNames[r.employment_status]||r.employment_status,離職日:r.departed_on||'',職稱:r.role,聘僱:r.employment_type,薪酬基準:r.pay_basis,出勤分鐘:r.work_minutes,服務分鐘:r.service_minutes,完成堂數:r.completed_count,已結帳堂數:r.service_count,待結帳堂數:r.unsettled_completed_count,退款堂數:r.refunded_service_count,服務業績:r.service_sales_cents/100,商品業績:r.product_sales_cents/100,本薪:r.base_cents/100,療程提成:r.service_commission_cents/100,商品提成:r.product_commission_cents/100,指定獎金:r.designated_bonus_cents/100,加班費:r.overtime_cents/100,其他獎金:r.bonus_cents/100,津貼:r.allowance_cents/100,扣款:r.deduction_cents/100,應發合計:r.total_cents/100,警示:[r.commission_warning,r.overtime_warning].filter(Boolean).join('；')})));
 const titles={profiles:'職稱薪資設定',attendance:'登錄出勤',overtime:'登錄加班',adjustment:'薪資加扣項',rule:'建立薪資制度版本','delete-rule':'刪除薪資制度版本',tiers:'職稱抽成階梯',rates:'加班倍率設定',finalize:'確認薪資結算',reopen:'重開薪資結算',detail:'薪資計算明細'};
 return <>
  <div className="os-page-title payroll-title"><div><p className="eyebrow">PAYROLL</p><h2>技師薪資</h2><p className="muted">{from} ～ {to} · 只計入實際服務人員、已完成且已結帳的紀錄。</p></div><div className="actions"><button onClick={exportRows}>匯出 CSV</button><button onClick={()=>exportPayrollXlsx({rows:preview,from,to,rule:selected,rates:data.rates,tiers:data.tiers})}>匯出 XLSX</button></div></div>
  <nav className="payroll-tabs" aria-label="薪資功能">
   {[['summary','薪資結算'],['time','工時與加扣'],['policy','制度設定'],['history','結算紀錄']].map(([id,label])=><button type="button" key={id} className={tab===id?'active':''} aria-current={tab===id?'page':undefined} onClick={()=>setTab(id)}>{label}</button>)}
  </nav>
  {previewError&&<p role="alert" className="alert">{previewError}</p>}
  {tab==='summary'&&<section className="payroll-panel">
   <div className="card payroll-command"><div><span className="payroll-command-label">目前制度</span><strong>{selected?`v${selected.version_no} · ${selected.name}`:'尚未設定'}</strong><small>{selected?.status==='active'?'已啟用':'歷史版本'} · {selected?.effective_from||'—'}</small></div><Field label="試算版本"><select value={rule} onChange={e=>setRule(e.target.value)}>{data.rules.map(x=><option key={x.id} value={x.id}>v{x.version_no} · {x.name}</option>)}</select></Field>{canManage&&<div className="actions"><button onClick={()=>setModal({kind:'adjustment'})}>加扣項</button><button onClick={()=>rpc('spa_payroll_run_save',{p_from:from,p_to:to,p_rule:rule,p_finalize:false}).then(onReload)}>儲存草稿</button><button className="primary" onClick={()=>setModal({kind:'finalize'})}>確認結算</button></div>}</div>
   <div className="payroll-kpis"><article className="card"><span>本期應發</span><strong>{money(total)}</strong></article><article className="card"><span>計抽服務營業額</span><strong>{money(serviceRevenue)}</strong></article><article className="card"><span>抽成與指定客</span><strong>{money(commissionTotal)}</strong></article><article className={`card ${unsettled||warningCount?'needs-attention':''}`}><span>待處理</span><strong>{unsettled+warningCount}</strong><small>{unsettled} 堂待結帳 · {warningCount} 個警示</small></article></div>
   {(unsettled>0||warningCount>0)&&<div className="payroll-notice">{unsettled>0&&<span>{unsettled} 堂完成服務尚未結帳，不會提前計薪。</span>}{warningCount>0&&<span>{warningCount} 位人員有出勤或加班警示。</span>}</div>}
   <PayrollSummaryTable rows={preview} total={total} settled={settled} onDetail={row=>setModal({kind:'detail',row})}/>
   <p className="muted payroll-footnote">點選「明細」可核對預約、POS 服務、商品銷售與實際技師歸屬；離職人員只在仍需結算的期間顯示。</p>
  </section>}
  {tab==='time'&&<PayrollTimePanel data={data} canManage={canManage} open={kind=>setModal({kind})}/>}
  {tab==='policy'&&<PayrollPolicyPanel data={data} rule={selected} canManage={canManage} onSelect={setRule} open={(kind,extra={})=>setModal({kind,...extra})}/>}
  {tab==='history'&&<PayrollHistory runs={data.runs||[]} canManage={canManage} open={run=>setModal({kind:'reopen',run})}/>}
  {modal&&<Modal title={titles[modal.kind]} onClose={()=>setModal(null)}>
   {modal.kind==='profiles'&&<CompensationProfilesForm data={data} saved={saved}/>}
   {modal.kind==='attendance'&&<TimeEntryForm staff={staff} saved={saved}/>}
   {modal.kind==='overtime'&&<OvertimeForm staff={staff} saved={saved}/>}
   {modal.kind==='adjustment'&&<AdjustmentForm staff={staff} period={from} saved={saved}/>}
   {modal.kind==='rule'&&<RuleForm current={data.rules.find(x=>x.id===activeRuleId)} saved={saved}/>}
   {modal.kind==='delete-rule'&&<PayrollRuleDeleteForm rule={modal.rule} saved={saved}/>}
   {modal.kind==='tiers'&&<PayrollComponentsForm rule={selected} data={data} saved={saved} section="tiers"/>}
   {modal.kind==='rates'&&<PayrollComponentsForm rule={selected} data={data} saved={saved} section="rates"/>}
   {modal.kind==='detail'&&<PayrollDetail row={modal.row} from={from} to={to}/>}
   {modal.kind==='finalize'&&<MutationForm action={()=>rpc('spa_payroll_run_save',{p_from:from,p_to:to,p_rule:rule,p_finalize:true})} onSaved={saved} submit="確認結算並鎖定"><p>將鎖定 {from} ～ {to} 的薪資，共 {preview.length} 人、{money(total)}。</p><p className="alert">鎖定後需要填寫原因才能重開，歷史計算會保留。</p></MutationForm>}
   {modal.kind==='reopen'&&<ReopenForm run={modal.run} saved={saved}/>}
  </Modal>}
 </>;
}

function PayrollSummaryTable({rows,total,settled,onDetail}){
 const sum=(row,...keys)=>keys.reduce((value,key)=>value+Number(row[key]||0),0);
 return <div className="table-wrap payroll-table-wrap"><table className="payroll-compact"><thead><tr><th>技師</th><th>出勤／服務</th><th>服務與業績</th><th>本薪</th><th>抽成</th><th>加班／加扣</th><th>應發</th><th></th></tr></thead><tbody>{rows.map(row=>{const commission=sum(row,'service_commission_cents','product_commission_cents','designated_bonus_cents'),adjustment=sum(row,'bonus_cents','allowance_cents')-Number(row.deduction_cents||0);return <tr key={row.staff_id} className={row.commission_warning||row.overtime_warning?'has-warning':''}><td className="payroll-person-cell" data-label="技師"><strong>{row.employee}</strong><span className="badge">{row.employment_type}</span><small>{row.role}{row.departed_on?` · 離職 ${row.departed_on}`:''}</small>{row.commission_warning&&<em>{row.commission_warning}</em>}{row.overtime_warning&&<em>{row.overtime_warning}</em>}</td><td data-label="出勤／服務"><strong>{(Number(row.work_minutes)/60).toFixed(1)} / {(Number(row.service_minutes)/60).toFixed(1)} h</strong><small>出勤／服務</small></td><td data-label="服務與業績"><strong>{row.service_count} 堂 · {money(row.service_sales_cents)}</strong>{Number(row.unsettled_completed_count)>0&&<small className="warn-text">待結 {row.unsettled_completed_count} 堂</small>}</td><td data-label="本薪">{money(row.base_cents)}</td><td data-label="抽成"><strong>{money(commission)}</strong><small>服務 {money(row.service_commission_cents)} · 商品 {money(row.product_commission_cents)} · 指定 {money(row.designated_bonus_cents)}</small></td><td data-label="加班／加扣"><strong>{money(Number(row.overtime_cents)+adjustment)}</strong><small>加班 {money(row.overtime_cents)} · 加扣 {adjustment>=0?'+':''}{money(adjustment)}</small></td><td data-label="應發" className="payroll-total-cell"><strong>{money(row.total_cents)}</strong></td><td className="payroll-detail-cell"><button type="button" className="link-button" onClick={()=>onDetail(row)}>明細</button></td></tr>})}</tbody><tfoot><tr><td colSpan="2">合計 · {rows.length} 人</td><td>{settled} 堂</td><td></td><td></td><td></td><td><strong>{money(total)}</strong></td><td></td></tr></tfoot></table>{!rows.length&&<Empty>本期沒有需要計算的人員。</Empty>}</div>;
}

function PayrollTimePanel({data,canManage,open}){
 const entries=(data.time_entries||[]).slice(0,10),overtime=(data.overtime||[]).slice(0,10),adjustments=(data.adjustments||[]).slice(0,10);
 const worked=row=>Math.max(0,(new Date(row.ended_at)-new Date(row.started_at))/60000-Number(row.break_minutes||0));
 return <section className="payroll-panel"><div className="payroll-section-head"><div><h2>工時與加扣</h2><p className="muted">出勤決定時薪與資格；服務時數仍由已結帳療程自動累計。</p></div>{canManage&&<div className="actions"><button className="primary" onClick={()=>open('attendance')}>登錄出勤</button><button onClick={()=>open('overtime')}>登錄加班</button><button onClick={()=>open('adjustment')}>加扣項</button></div>}</div><div className="payroll-record-grid"><article className="card"><h3>最近出勤</h3>{!entries.length?<Empty>本期尚無出勤紀錄。</Empty>:<div className="table-wrap"><table><thead><tr><th>日期</th><th>人員</th><th>時數</th></tr></thead><tbody>{entries.map(row=><tr key={row.id}><td>{row.work_date}</td><td>{row.employee}</td><td>{(worked(row)/60).toFixed(1)} h</td></tr>)}</tbody></table></div>}</article><article className="card"><h3>最近加班</h3>{!overtime.length?<Empty>本期尚無加班紀錄。</Empty>:<div className="table-wrap"><table><thead><tr><th>日期</th><th>人員</th><th>類型／時數</th></tr></thead><tbody>{overtime.map(row=><tr key={row.id}><td>{row.work_date}</td><td>{row.employee}</td><td>{overtimeNames[row.overtime_type]} · {(Number(row.minutes)/60).toFixed(1)} h</td></tr>)}</tbody></table></div>}</article><article className="card"><h3>本期加扣</h3>{!adjustments.length?<Empty>本期尚無加扣項。</Empty>:<div className="table-wrap"><table><thead><tr><th>人員</th><th>類型</th><th>金額</th></tr></thead><tbody>{adjustments.map(row=><tr key={row.id}><td>{row.employee}</td><td>{{bonus:'獎金',allowance:'津貼',deduction:'扣款',designated_bonus:'指定客'}[row.kind]||row.kind}</td><td>{row.kind==='deduction'?'-':'+'}{money(row.amount_cents)}</td></tr>)}</tbody></table></div>}</article></div></section>;
}

function PayrollPolicyPanel({data,rule,canManage,open,onSelect}){
 const activeTiers=(data.tiers||[]).filter(row=>row.rule_version_id===rule?.id),profileCount=(data.compensation_profiles||[]).length;
 const policy=(code,label,summary)=>{const tiers=activeTiers.filter(row=>row.employment_type_code===code),rates=tiers.map(row=>Number(row.rate_bps)/100),starts=tiers.filter(row=>row.metric==='service_minutes').map(row=>Number(row.threshold_from)/60);return {code,label,summary,count:tiers.length,range:rates.length?`${Math.min(...rates)}%–${Math.max(...rates)}%`:'使用職稱基本比例',start:starts.length?`${Math.min(...starts)} 小時起算`:'按堂數／業績'};};
 const cards=[policy('full_time','正職','月薪 · 前 65 服務小時由底薪涵蓋'),policy('part_time','兼職','時薪 · 出勤滿 40 小時才有抽成資格'),policy('contractor','承攬','前 100 堂 30% · 後續 40%')];
 return <section className="payroll-panel"><article className="card payroll-policy-hero"><div><span className="badge">{rule?.status==='active'?'啟用中':'歷史版本'}</span><h2>{rule?`v${rule.version_no} · ${rule.name}`:'尚未建立制度'}</h2><p>{rule?`${rule.effective_from} 生效 · 月薪換算時薪除數 ${rule.hourly_divisor}`:''}</p></div>{canManage&&<button className="primary" onClick={()=>open('rule')}>＋ 建立新版本</button>}</article><div className="payroll-version-list card"><div className="payroll-section-head"><div><h3>制度版本</h3><p className="muted">新版本會複製目前倍率與抽成；有結算記錄的歷史版本會保留。</p></div></div>{data.rules.map(item=>{const inUse=(data.runs||[]).some(run=>run.rule_version_id===item.id);return <div className={`payroll-version-row ${item.id===rule?.id?'selected':''}`} key={item.id}><button type="button" className="payroll-version-select" onClick={()=>onSelect(item.id)}><span className="badge">v{item.version_no}</span><span><strong>{item.name}</strong><small>{item.effective_from} · {item.status==='active'?'啟用中':'歷史版本'}{inUse?' · 已有結算':''}</small></span></button>{canManage&&item.status!=='active'&&<button type="button" className="danger" disabled={inUse} title={inUse?'已有薪資結算，不能刪除':''} onClick={()=>open('delete-rule',{rule:item})}>{inUse?'保留':'刪除'}</button>}</div>;})}</div><div className="payroll-policy-grid">{cards.map(item=><article className="card" key={item.code}><span className="payroll-policy-index">{item.label}</span><h3>{item.summary}</h3><p><strong>{item.range}</strong></p><p className="muted">{item.start} · {item.count} 條職稱階梯</p></article>)}</div><div className="payroll-settings-grid"><article className="card"><h3>1 · 職稱薪資</h3><p>底薪／時薪、商品提成、指定客比例和資格門檻。</p><small>{profileCount} 組職稱 × 聘僱設定</small>{canManage&&<button className="primary" onClick={()=>open('profiles')}>編輯職稱薪資</button>}</article><article className="card"><h3>2 · 抽成階梯</h3><p>正職、兼職與承攬的時數／堂數級距。</p><small>預設採用《技師薪資制度》</small>{canManage&&rule?.status==='active'&&<button className="primary" onClick={()=>open('tiers')}>編輯抽成表</button>}</article><article className="card"><h3>3 · 加班制度</h3><p>平日、休息日及假日的分鐘區間與倍率。</p><small>一般月上限 {Number(rule?.monthly_overtime_limit_minutes||0)/60} 小時</small>{canManage&&rule?.status==='active'&&<button className="primary" onClick={()=>open('rates')}>編輯加班倍率</button>}</article></div><p className="muted payroll-footnote">所有數值都可修改；建立新版本後，舊結算繼續保留原制度快照。</p></section>;
}

function PayrollHistory({runs,canManage,open}){
 return <section className="payroll-panel"><div className="payroll-section-head"><div><h2>結算紀錄</h2><p className="muted">鎖定後的薪資保留人員、制度與計算快照。</p></div></div>{!runs.length?<Empty>尚無結算紀錄。</Empty>:<div className="card table-wrap"><table><thead><tr><th>期間</th><th>狀態</th><th>鎖定時間</th><th></th></tr></thead><tbody>{runs.map(run=><tr key={run.id}><td><strong>{run.period_start} ～ {run.period_end}</strong></td><td><span className="badge">{run.status==='finalized'?'已鎖定':'草稿'}</span></td><td>{run.finalized_at?dateTime(run.finalized_at):'—'}</td><td>{canManage&&run.status==='finalized'&&<button onClick={()=>open(run)}>重開</button>}</td></tr>)}</tbody></table></div>}</section>;
}

function PayrollDetail({row,from,to}){
 const [data,setData]=useState(null),[error,setError]=useState('');
 useEffect(()=>{let live=true;rpc('spa_payroll_staff_detail',{p_staff:row.staff_id,p_from:from,p_to:to}).then(value=>{if(live)setData(value);}).catch(e=>{if(live)setError(errorText(e));});return()=>{live=false;};},[row.staff_id,from,to]);
 if(error)return <p className="alert">{error}</p>;if(!data)return <Empty>正在載入來源記錄…</Empty>;
 return <><p><strong>{row.employee}</strong> · {row.role} · {from} ～ {to}</p><div className="grid"><article className="card"><p className="muted">完成／已結帳／待結帳</p><div className="metric">{row.completed_count} / {row.service_count} / {row.unsettled_completed_count}</div></article><article className="card"><p className="muted">服務收入／提成</p><div className="metric">{money(row.service_sales_cents)} / {money(row.service_commission_cents)}</div></article></div><h3>預約服務記錄</h3>{!data.services.length&&<Empty>本期沒有完成療程。</Empty>}<div className="table-wrap"><table><thead><tr><th>日期／預約</th><th>療程</th><th>狀態</th><th>收入</th><th>提成</th><th>評價</th></tr></thead><tbody>{data.services.map(item=><tr key={item.id}><td>{item.business_date}<small className="table-sub">{item.reference}</small></td><td>{item.service_name}<small className="table-sub">{item.service_minutes} 分</small></td><td><span className="badge">{{settled:'已結帳',unsettled:'待結帳',refunded:'已退款'}[item.settlement_status]}</span></td><td>{item.revenue_cents==null?'—':money(item.revenue_cents)}</td><td>{item.commission_cents==null?'—':money(item.commission_cents)}</td><td>{item.review_count}</td></tr>)}</tbody></table></div><h3>POS 服務項目</h3>{!data.pos_services?.length&&<Empty>本期沒有 POS 服務。</Empty>}{data.pos_services?.map(item=><p key={`${item.id}-${item.name_snapshot}`}>{dateTime(item.paid_at)} · {item.reference} · {item.name_snapshot} × {item.quantity} · {money(item.line_total_cents)} · 提成 {money(item.commission_cents)}</p>)}<h3>計入商品訂單</h3>{!data.product_orders.length&&<Empty>本期沒有計入商品訂單。</Empty>}{data.product_orders.map(item=><p key={`${item.id}-${item.name_snapshot}`}>{item.reference} · {item.name_snapshot} × {item.quantity} · {money(item.line_total_cents)} · 提成 {money(item.commission_cents)}</p>)}<p className="muted">預約依目前實際技師計入；POS 服務與商品依結帳時指定人員計入。更換技師會保存完整變更與提成紀錄。</p></>;
}

function CompensationProfilesForm({data,saved}){
 const profiles=data.compensation_profiles||[];
 const [key,setKey]=useState(()=>profiles[0]?`${profiles[0].job_title_id}|${profiles[0].employment_type_code}`:'');
 const current=profiles.find(x=>`${x.job_title_id}|${x.employment_type_code}`===key)||profiles[0]||{};
 const [f,setF]=useState({});
 useEffect(()=>{setF({pay_basis:current.pay_basis||'monthly',base_pay:Number(current.base_pay_cents||0)/100,service_commission:Number(current.service_commission_bps||0)/100,product_commission:Number(current.product_commission_bps||0)/100,designated_bonus:Number(current.designated_client_bonus_bps||0)/100,minimum_attendance:Number(current.minimum_attendance_minutes||0)/60,commission_start:Number(current.commission_start_service_minutes||0)/60,active:current.active??true});},[key]);
 return <MutationForm action={()=>rpc('spa_compensation_profile_save_v2',{p_job_title:current.job_title_id,p_employment_type:current.employment_type_code,p_pay_basis:f.pay_basis,p_base_pay:cents(f.base_pay||0),p_service_commission:Math.round(Number(f.service_commission||0)*100),p_product_commission:Math.round(Number(f.product_commission||0)*100),p_designated_bonus_bps:Math.round(Number(f.designated_bonus||0)*100),p_minimum_attendance_minutes:Math.round(Number(f.minimum_attendance||0)*60),p_commission_start_service_minutes:Math.round(Number(f.commission_start||0)*60),p_active:f.active})} onSaved={saved} submit="儲存並套用"><p className="muted">同一職稱及聘僱類型共用一套規則。商品銷售在 POS 指定銷售人員後，商品提成會直接進入該人員薪資；指定客獎金按該客人實際完成且未退款的服務收入比例計算。</p><Field label="職稱 × 聘僱類型"><select value={key} onChange={e=>setKey(e.target.value)}>{profiles.map(x=><option key={`${x.job_title_id}-${x.employment_type_code}`} value={`${x.job_title_id}|${x.employment_type_code}`}>{x.job_title_name} · {x.employment_type_name}</option>)}</select></Field><div className="form-grid"><Field label="薪酬基準"><select value={f.pay_basis||'monthly'} onChange={e=>setF(v=>({...v,pay_basis:e.target.value}))}><option value="monthly">月薪</option><option value="hourly">時薪</option><option value="session">每堂薪酬</option></select></Field><Field label={`基本薪酬 NT$（${f.pay_basis==='hourly'?'每小時':f.pay_basis==='session'?'每堂':'每月'}）`}><input type="number" min="0" step="0.01" value={f.base_pay??''} onChange={e=>setF(v=>({...v,base_pay:e.target.value}))}/></Field><Field label="無階梯時的服務提成（%）"><input type="number" min="0" max="100" step="0.01" value={f.service_commission??''} onChange={e=>setF(v=>({...v,service_commission:e.target.value}))}/></Field><Field label="商品銷售提成（%）"><input type="number" min="0" max="100" step="0.01" value={f.product_commission??''} onChange={e=>setF(v=>({...v,product_commission:e.target.value}))}/></Field><Field label="指定客加成（該堂服務收入 %）"><input type="number" min="0" max="100" step="0.01" value={f.designated_bonus??''} onChange={e=>setF(v=>({...v,designated_bonus:e.target.value}))}/></Field><Field label="提成資格：最低出勤（小時／月）"><input type="number" min="0" max="1000" step="0.5" value={f.minimum_attendance??''} onChange={e=>setF(v=>({...v,minimum_attendance:e.target.value}))}/></Field><Field label="服務提成起算（服務小時／月）"><input type="number" min="0" max="1000" step="0.5" value={f.commission_start??''} onChange={e=>setF(v=>({...v,commission_start:e.target.value}))}/></Field><Field label="規則狀態"><select value={String(f.active??true)} onChange={e=>setF(v=>({...v,active:e.target.value==='true'}))}><option value="true">啟用</option><option value="false">停用</option></select></Field></div><p className="muted">金額輸入新台幣元；比例輸入百分比；出勤與服務門檻輸入小時。系統內部以分、基點和分鐘保存，避免單位與小數誤差。已有職稱階梯時，以階梯為準。</p></MutationForm>;
}
function TimeEntryForm({staff,saved}){
 const people=staff.filter(x=>x.active&&!x.archived_at),[person,setPerson]=useState(people[0]?.id||''),[date,setDate]=useState(taipeiDate()),[start,setStart]=useState('10:00'),[end,setEnd]=useState('18:00'),[breakMinutes,setBreakMinutes]=useState(60),[note,setNote]=useState('');
 const stamp=value=>`${date}T${value}:00+08:00`;
 return <MutationForm action={()=>rpc('spa_time_entry_save',{p_id:null,p_staff:person,p_work_date:date,p_started_at:stamp(start),p_ended_at:stamp(end),p_break_minutes:Number(breakMinutes),p_note:note})} onSaved={saved}><Field label="員工"><select required value={person} onChange={e=>setPerson(e.target.value)}>{people.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><div className="form-grid"><Field label="出勤日期"><input required type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="上班時間"><input required type="time" value={start} onChange={e=>setStart(e.target.value)}/></Field><Field label="下班時間"><input required type="time" value={end} onChange={e=>setEnd(e.target.value)}/></Field><Field label="休息分鐘"><input required type="number" min="0" max="720" step="1" value={breakMinutes} onChange={e=>setBreakMinutes(e.target.value)}/></Field></div><Field label="備註"><textarea value={note} onChange={e=>setNote(e.target.value)}/></Field><p className="muted">出勤小時用於兼職基本工資和提成資格；服務小時只取已完成、已結帳且未退款的療程，兩者分開計算。</p></MutationForm>;
}
function OvertimeForm({staff,saved}){const people=staff.filter(x=>x.active&&!x.archived_at),[person,setPerson]=useState(people[0]?.id||''),[date,setDate]=useState(taipeiDate()),[type,setType]=useState('weekday'),[minutes,setMinutes]=useState(60),[reason,setReason]=useState('');return <MutationForm action={()=>rpc('spa_overtime_save',{p_staff:person,p_date:date,p_type:type,p_minutes:Number(minutes),p_reason:reason})} onSaved={saved}><Field label="員工"><select required value={person} onChange={e=>setPerson(e.target.value)}>{people.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></Field><Field label="日期"><input required type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="加班類型"><select value={type} onChange={e=>setType(e.target.value)}>{Object.entries(overtimeNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></Field><Field label="分鐘"><input required type="number" min="1" max="720" value={minutes} onChange={e=>setMinutes(e.target.value)}/></Field><Field label="原因"><textarea required value={reason} onChange={e=>setReason(e.target.value)}/></Field></MutationForm>}
function AdjustmentForm({staff,period,saved}){const people=staff.filter(x=>['active','departed'].includes(x.employment_status||(x.active?'active':'inactive'))&&!x.archived_at),[person,setPerson]=useState(people[0]?.id||''),[kind,setKind]=useState('bonus'),[amount,setAmount]=useState(''),[note,setNote]=useState('');return <MutationForm action={()=>rpc('spa_payroll_adjustment_save',{p_staff:person,p_period:period,p_kind:kind,p_cents:cents(amount),p_note:note})} onSaved={saved}><Field label="員工"><select value={person} onChange={e=>setPerson(e.target.value)}>{people.map(x=><option key={x.id} value={x.id}>{x.name}{x.employment_status==='departed'?'（已離職）':''}</option>)}</select></Field><Field label="類型"><select value={kind} onChange={e=>setKind(e.target.value)}><option value="bonus">獎金</option><option value="allowance">津貼</option><option value="deduction">扣款</option><option value="designated_bonus">指定客獎金</option></select></Field><Field label="金額 NT$"><input required type="number" min="0" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)}/></Field><Field label="說明"><textarea required value={note} onChange={e=>setNote(e.target.value)}/></Field></MutationForm>}
function PayrollComponentsForm({rule,data,saved,section='tiers'}){
 const metricNames={service_minutes:'服務時數（小時）',service_count:'服務堂數',service_sales_cents:'服務業績（NT$）',product_sales_cents:'商品業績（NT$）'};
 const profiles=data.compensation_profiles||[],[scope,setScope]=useState(()=>profiles[0]?`${profiles[0].job_title_id}|${profiles[0].employment_type_code}`:'');
 const [scopeTitle,scopeEmployment]=scope.split('|');
 const [rates,setRates]=useState(data.rates.filter(x=>x.rule_version_id===rule.id).map(x=>({...x,multiplier_percent:Number(x.multiplier_bps)/100})));
 const displayThreshold=(metric,value)=>['service_sales_cents','product_sales_cents'].includes(metric)?Number(value)/100:metric==='service_minutes'?Number(value)/60:Number(value);
 const [tiers,setTiers]=useState(data.tiers.filter(x=>x.rule_version_id===rule.id).map(x=>({...x,calculation_mode:x.calculation_mode||'progressive',threshold_from_value:displayThreshold(x.metric,x.threshold_from),threshold_to_value:x.threshold_to==null?'':displayThreshold(x.metric,x.threshold_to),rate_percent:Number(x.rate_bps)/100})));
 const changeRate=(index,key,value)=>setRates(rows=>rows.map((row,i)=>i===index?{...row,[key]:value}:row));
 const changeTier=(index,key,value)=>setTiers(rows=>rows.map((row,i)=>i===index?{...row,[key]:value}:row));
 const addTier=()=>setTiers(rows=>[...rows,{job_title_id:scopeTitle,employment_type_code:scopeEmployment,metric:scopeEmployment==='contractor'?'service_count':'service_minutes',calculation_mode:'progressive',threshold_from_value:0,threshold_to_value:'',rate_percent:0,service_category_id:null}]);
 const payloadRates=rates.map(({employment_type_code,overtime_type,start_minute,end_minute,multiplier_percent})=>({employment_type_code,overtime_type,start_minute:Number(start_minute),end_minute:Number(end_minute),multiplier_bps:Math.round(Number(multiplier_percent)*100)}));
 const payloadTiers=tiers.map(row=>{const scale=['service_sales_cents','product_sales_cents'].includes(row.metric)?100:row.metric==='service_minutes'?60:1;return {job_title_id:row.job_title_id,employment_type_code:row.employment_type_code,metric:row.metric,calculation_mode:row.calculation_mode||'progressive',threshold_from:Math.round(Number(row.threshold_from_value)*scale),threshold_to:row.threshold_to_value===''?null:Math.round(Number(row.threshold_to_value)*scale),rate_bps:Math.round(Number(row.rate_percent)*100),service_category_id:row.service_category_id||null};});
 const visible=tiers.map((row,index)=>({...row,index})).filter(row=>row.job_title_id===scopeTitle&&row.employment_type_code===scopeEmployment),employmentName=code=>data.employment_types?.find(x=>x.code===code)?.name||code;
 const hints={full_time:'預設：前 65 服務小時由底薪涵蓋，第 66 小時起每 10 小時一個累進區間，最高 35%。',part_time:'預設：出勤滿 40 小時後，服務時數按 5%～30% 累進。',contractor:'預設：前 100 堂 30%，第 101 堂起 40%。'};
 return <MutationForm action={()=>rpc('spa_payroll_components_save_v2',{p_rule:rule.id,p_rates:payloadRates,p_tiers:payloadTiers})} onSaved={saved} submit={section==='rates'?'儲存加班倍率':'儲存抽成表'}>
  <div className="payroll-editor-heading"><div><span className="badge">v{rule.version_no}</span><strong>{rule.name}</strong></div><small>修改只影響此啟用版本；歷史結算保留原快照。</small></div>
  {section==='rates'&&<><p className="payroll-form-hint">按加班類型和聘僱方式設定分鐘區間。134% 代表 1.34 倍。</p><div className="table-wrap"><table className="payroll-editor-table"><thead><tr><th>聘僱</th><th>加班類型</th><th>分鐘區間</th><th>倍率</th></tr></thead><tbody>{rates.map((row,index)=><tr key={`${row.employment_type_code}-${row.overtime_type}-${row.start_minute}`}><td>{employmentName(row.employment_type_code)}</td><td>{overtimeNames[row.overtime_type]}</td><td><div className="payroll-range-input"><input aria-label="開始分鐘" type="number" min="0" max="719" value={row.start_minute} onChange={e=>changeRate(index,'start_minute',e.target.value)}/><span>–</span><input aria-label="結束分鐘" type="number" min="1" max="720" value={row.end_minute} onChange={e=>changeRate(index,'end_minute',e.target.value)}/></div></td><td><div className="payroll-suffix-input"><input aria-label="加班倍率" type="number" min="0" max="1000" step="0.01" value={row.multiplier_percent} onChange={e=>changeRate(index,'multiplier_percent',e.target.value)}/><span>%</span></div></td></tr>)}</tbody></table></div></>}
  {section==='tiers'&&<><Field label="職稱 × 聘僱類型"><select value={scope} onChange={e=>setScope(e.target.value)}>{profiles.map(x=><option key={`${x.job_title_id}-${x.employment_type_code}`} value={`${x.job_title_id}|${x.employment_type_code}`}>{x.job_title_name} · {x.employment_type_name}</option>)}</select></Field><p className="payroll-form-hint">{hints[scopeEmployment]||'設定此組合的抽成區間。'} 累進表示只計算落在該區間的服務收入。</p><div className="payroll-editor-actions"><strong>抽成級距</strong><button type="button" onClick={addTier}>新增一階</button></div>{!visible.length?<Empty>此組合尚未設定階梯，將使用職稱薪資中的基本提成。</Empty>:<div className="table-wrap"><table className="payroll-editor-table"><thead><tr><th>計算依據</th><th>區間</th><th>比例</th><th>方式</th><th></th></tr></thead><tbody>{visible.map(row=><tr key={row.id||row.index}><td><select value={row.metric} onChange={e=>changeTier(row.index,'metric',e.target.value)}>{Object.entries(metricNames).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></td><td><div className="payroll-range-input"><input aria-label="階梯起點" type="number" min="0" step="0.01" value={row.threshold_from_value} onChange={e=>changeTier(row.index,'threshold_from_value',e.target.value)}/><span>–</span><input aria-label="階梯終點" type="number" min="0" step="0.01" placeholder="以上" value={row.threshold_to_value} onChange={e=>changeTier(row.index,'threshold_to_value',e.target.value)}/></div></td><td><div className="payroll-suffix-input"><input aria-label="提成百分比" type="number" min="0" max="100" step="0.01" value={row.rate_percent} onChange={e=>changeTier(row.index,'rate_percent',e.target.value)}/><span>%</span></div></td><td><select aria-label="計算方式" value={row.calculation_mode||'progressive'} onChange={e=>changeTier(row.index,'calculation_mode',e.target.value)}><option value="progressive">累進</option><option value="flat">整段</option></select></td><td><button type="button" className="danger" onClick={()=>setTiers(rows=>rows.filter((_,i)=>i!==row.index))}>刪除</button></td></tr>)}</tbody></table></div>}<p className="muted">服務時數輸入小時、堂數輸入整數、業績輸入 NT$ 元。</p></>}
 </MutationForm>;
}
function RuleForm({current,saved}){const [name,setName]=useState(current?`${current.name}（新版本）`:'技師薪資制度'),[date,setDate]=useState(taipeiDate()),[divisor,setDivisor]=useState(current?.hourly_divisor||240),[include,setInclude]=useState(current?.include_regular_commission??true),[monthly,setMonthly]=useState((current?.monthly_overtime_limit_minutes||2760)/60),[agreed,setAgreed]=useState((current?.agreed_monthly_limit_minutes||3240)/60),[quarter,setQuarter]=useState((current?.quarterly_overtime_limit_minutes||8280)/60);return <MutationForm action={()=>rpc('spa_payroll_rule_create',{p_name:name,p_effective:date,p_divisor:Number(divisor),p_include_commission:include,p_monthly_limit:Number(monthly)*60,p_agreed_limit:Number(agreed)*60,p_quarter_limit:Number(quarter)*60})} onSaved={saved} submit="建立並啟用新版本"><p className="muted">建立後會自動啟用新版本，並把目前版本轉為歷史版本；現有結算快照不會改變。</p><Field label="版本名稱"><input required maxLength="120" value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="生效日"><input required type="date" value={date} onChange={e=>setDate(e.target.value)}/></Field><Field label="月薪換算時薪除數"><input type="number" min="1" value={divisor} onChange={e=>setDivisor(e.target.value)}/></Field><Field label="時薪基數包含經常性提成與指定客獎金"><select value={String(include)} onChange={e=>setInclude(e.target.value==='true')}><option value="true">包含</option><option value="false">不包含</option></select></Field><Field label="一般月上限（小時）"><input type="number" min="1" value={monthly} onChange={e=>setMonthly(e.target.value)}/></Field><Field label="勞資會議月上限（小時）"><input type="number" min="1" value={agreed} onChange={e=>setAgreed(e.target.value)}/></Field><Field label="季度上限（小時）"><input type="number" min="1" value={quarter} onChange={e=>setQuarter(e.target.value)}/></Field><p className="muted">預設對應試算表：除數 240、一般月上限 46 小時、同意上限 54 小時、季度上限 138 小時。新版本會複製現行倍率與提成級距。</p></MutationForm>}
function PayrollRuleDeleteForm({rule,saved}){const [confirmation,setConfirmation]=useState('');return <MutationForm action={()=>rpc('spa_payroll_rule_delete',{p_rule:rule.id,p_confirmation:confirmation})} onSaved={saved} submit="確認刪除版本"><p><strong>v{rule.version_no} · {rule.name}</strong></p><p className="alert">只可刪除未啟用且沒有薪資結算記錄的版本。此操作會同時刪除該版本的倍率與抽成級距。</p><Field label="輸入 DELETE 確認"><input required autoComplete="off" value={confirmation} onChange={e=>setConfirmation(e.target.value)} placeholder="DELETE"/></Field></MutationForm>}
