function RoleForm({row,saved}){const [code,setCode]=useState(row.code||''),[name,setName]=useState(row.name||''),[active,setActive]=useState(row.active??true);const permissions=['dashboard.view','appointments.view','reviews.view'];return <MutationForm action={()=>rpc('spa_role_profile_save',{p_code:code,p_name:name,p_permissions:permissions,p_active:active,p_display_order:row.display_order||100})} onSaved={saved}><Field label="角色代碼"><input required disabled={!!row.code} pattern="[a-z][a-z0-9_]{1,31}" value={code} onChange={e=>setCode(e.target.value.toLowerCase())}/></Field><Field label="角色名稱"><input required value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="狀態"><select value={String(active)} onChange={e=>setActive(e.target.value==='true')}><option value="true">啟用</option><option value="false">停用</option></select></Field><fieldset><legend>員工固定權限</legend><div className="os-permission-list"><span className="badge">營運首頁</span><span className="badge">預約與日程</span><span className="badge">評價</span><span className="badge">自己的薪資與績效</span></div><p className="muted">這些權限由系統強制保護，不能擴充到會員、收支、人事、商品或系統設定。</p></fieldset></MutationForm>}

export function SettingsOS({data,onReload}){
 const [modal,setModal]=useState(null);const saved=async()=>{setModal(null);await onReload();};
 const today=data.business_overrides.find(x=>x.business_date===taipeiDate());
 return <>
  <div className="os-page-title"><div><h2>系統設定</h2><p className="muted">門店、官網、預約、庫存與資源設定集中管理。</p></div></div>
  <div className="grid">
   <article className="card"><h3>門店資料與營業時間</h3><p>{data.business.name}</p><p>{data.business.phone}</p><p>{data.business.address}</p><p className="muted">每週營業時間會同步官網和預約空檔；特殊日期優先。</p><div className="actions"><button onClick={()=>setModal({kind:'business'})}>修改資料</button><button className="primary" onClick={()=>setModal({kind:'hours'})}>每週營業時間</button><button onClick={()=>setModal({kind:'override',row:today,date:taipeiDate()})}>今日營業／休假</button></div></article>
   <article className="card"><h3>官網同步</h3><p>預約按鈕：{data.website.booking_cta?'顯示':'隱藏'}</p><p>人員：{data.website.show_staff?'顯示':'隱藏'} · 商品：{data.website.show_products?'顯示':'隱藏'}</p><button onClick={()=>setModal({kind:'website'})}>修改</button></article>
   <article className="card"><h3>預約規則</h3><p>{data.booking.booking_days} 天內 · {data.booking.auto_confirm?'自動確認':'人工確認'}</p><p>取消期限 {data.booking.cancellation_hours} 小時</p><button onClick={()=>setModal({kind:'booking'})}>修改</button></article>
   <article className="card"><h3>零庫存顯示</h3><p>{data.inventory.zero_stock_behavior==='hide'?'自動隱藏':'顯示售罄'}</p><button onClick={()=>setModal({kind:'inventory'})}>修改</button></article>
  </div>
  <section className="card os-hours-overrides"><div className="os-page-title"><div><h2>特殊日期</h2><p className="muted">用於休假、節日或當日延長營業；設定後立即覆蓋每週時間。</p></div><button onClick={()=>setModal({kind:'override',row:null,date:taipeiDate()})}>新增特殊日期</button></div>{!data.business_overrides.length&&<Empty>未來 180 天沒有特殊營業設定。</Empty>}<div className="row">{data.business_overrides.map(row=><button className="os-date-chip" key={row.business_date} onClick={()=>setModal({kind:'override',row,date:row.business_date})}><strong>{row.business_date}</strong><span>{row.is_open?`${minuteLabel(row.opening_minute)}–${minuteLabel(row.closing_minute)}`:'休假'}</span><small>{row.note||'當日設定'}</small></button>)}</div></section>
  <h2>服務資源</h2><p className="muted">目前使用「床位」作為資源；預約引擎依啟用資源數量阻止超賣。</p><div className="row">{data.resources.map(r=><article className="card" key={r.id}><h3>{r.name}</h3><span className="badge">{r.active?'啟用':'停用'}</span><button onClick={()=>setModal({kind:'room',row:r})}>修改</button></article>)}<button onClick={()=>setModal({kind:'room',row:null})}>新增床位</button></div>
  <ResetDataPanel onReload={onReload}/>
  {modal&&<Modal title={{business:'門店資料',hours:'每週營業時間',override:'特殊日期營業設定',website:'官網同步',inventory:'庫存顯示',booking:'預約規則',room:'床位設定'}[modal.kind]||'系統設定'} onClose={()=>setModal(null)}>{modal.kind==='business'&&<JsonSettingForm settingKey="business" value={data.business} fields={[["name","門店名稱"],["phone","電話"],["address","地址"],["timezone","時區"]]} saved={saved}/>} {modal.kind==='hours'&&<BusinessHoursForm value={data.business_hours} saved={saved}/>} {modal.kind==='override'&&<DayOverrideForm date={modal.date} value={modal.row} saved={saved}/>} {modal.kind==='website'&&<WebsiteSettingForm value={data.website} saved={saved}/>} {modal.kind==='inventory'&&<InventorySettingForm value={data.inventory} saved={saved}/>} {modal.kind==='booking'&&<BookingSettingForm value={data.booking} saved={saved}/>} {modal.kind==='room'&&<ResourceForm row={modal.row} saved={saved}/>}</Modal>}
 </>;
}

const timeChoices=Array.from({length:97},(_,i)=>i*30);
function BusinessHoursForm({value,saved}){
 const [rows,setRows]=useState([0,1,2,3,4,5,6].map(weekday=>value.find(x=>x.weekday===weekday)||{weekday,is_open:true,opening_minute:600,closing_minute:1560}));
 const change=(weekday,key,next)=>setRows(list=>list.map(row=>row.weekday===weekday?{...row,[key]:next,...(key==='opening_minute'&&next>=row.closing_minute?{closing_minute:Math.min(2880,next+60)}:{})}:row));
 return <MutationForm action={()=>rpc('spa_business_hours_save',{p_hours:rows})} onSaved={saved} submit="儲存每週營業時間"><p className="muted">結束時間可跨至翌日。修改後會立即影響官網顯示、新預約和顧客自行改期；既有預約保持不變。</p><div className="os-hours-grid">{rows.map(row=><div className={`os-hours-row ${row.is_open?'':'is-closed'}`} key={row.weekday}><strong>週{'日一二三四五六'[row.weekday]}</strong><label className="auto-refresh"><input type="checkbox" checked={row.is_open} onChange={e=>change(row.weekday,'is_open',e.target.checked)}/>{row.is_open?'營業':'休息'}</label><select aria-label={`週${'日一二三四五六'[row.weekday]}開始`} disabled={!row.is_open} value={row.opening_minute} onChange={e=>change(row.weekday,'opening_minute',Number(e.target.value))}>{timeChoices.slice(0,49).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select><span>至</span><select aria-label={`週${'日一二三四五六'[row.weekday]}結束`} disabled={!row.is_open} value={row.closing_minute} onChange={e=>change(row.weekday,'closing_minute',Number(e.target.value))}>{timeChoices.filter(n=>n>row.opening_minute).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></div>)}</div></MutationForm>;
}
function DayOverrideForm({date,value,saved}){
 const [day,setDay]=useState(value?.business_date||date||taipeiDate()),[isOpen,setOpen]=useState(value?.is_open??true),[opening,setOpening]=useState(value?.opening_minute??600),[closing,setClosing]=useState(value?.closing_minute??1560),[note,setNote]=useState(value?.note||''),[restoreBusy,setRestoreBusy]=useState(false),[restoreError,setRestoreError]=useState('');
 const hasOverride=value?.source==='override'||!!value?.business_date;
 async function restore(){setRestoreBusy(true);setRestoreError('');try{await rpc('spa_business_day_override_delete',{p_date:day});await saved();}catch(e){setRestoreError(errorText(e));setRestoreBusy(false);}}
 return <><MutationForm action={()=>rpc('spa_business_day_override_save',{p_date:day,p_is_open:isOpen,p_open:Number(opening),p_close:Number(closing),p_note:note})} onSaved={saved} submit="套用至官網與預約"><div className="form-grid"><Field label="日期"><input type="date" required disabled={!!value?.business_date} value={day} onChange={e=>setDay(e.target.value)}/></Field><Field label="狀態"><select value={String(isOpen)} onChange={e=>setOpen(e.target.value==='true')}><option value="true">營業</option><option value="false">休假／不開放預約</option></select></Field>{isOpen&&<><Field label="開始"><select value={opening} onChange={e=>{const n=Number(e.target.value);setOpening(n);if(n>=closing)setClosing(Math.min(2880,n+60));}}>{timeChoices.slice(0,49).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field><Field label="結束（可至翌日）"><select value={closing} onChange={e=>setClosing(Number(e.target.value))}>{timeChoices.filter(n=>n>opening).map(n=><option key={n} value={n}>{minuteLabel(n)}</option>)}</select></Field></>}<Field wide label="說明"><input maxLength="500" placeholder={isOpen?'例如：節日延長營業':'例如：店休'} value={note} onChange={e=>setNote(e.target.value)}/></Field></div><p className="muted">此設定不會取消既有預約；休假後官網不會再產生該日新空檔。</p></MutationForm>{hasOverride&&<div className="os-restore-hours"><button type="button" disabled={restoreBusy} onClick={restore}>恢復每週時間</button>{restoreError&&<p className="alert" role="alert">{restoreError}</p>}</div>}</>;
}

const resetScopes={appointments:['預約、完成數與療程收款','連動清除預約、結帳、評價、預約憑證及相關儲值／套票／現金流水；已扣點數或堂數會回復。'],orders:['商品訂單','連動清除訂單明細、訂單庫存變動與商品收款，售出庫存會回補。'],reviews:['評價與匿名建議','單獨清除所選期間建立的評價和建議。'],payroll:['薪資與工時','連動清除薪資結算、工時、加班與薪資調整。'],expenses:['門店支出','單獨清除所選期間記錄的費用支出。'],all:['全部營運記錄','組合以上範圍；保留會員檔案及儲值／套票購買記錄、員工帳號、療程商品、庫存主資料與系統設定。']};
function resetRange(mode){const today=taipeiDate();if(mode==='all')return {from:null,to:null};if(mode==='today')return {from:today,to:today};if(mode==='week'){const dow=new Date(`${today}T00:00:00Z`).getUTCDay();const from=dateAfter(-(dow===0?6:dow-1),today);return {from,to:dateAfter(6,from)};}const from=today.slice(0,8)+'01';const month=Number(today.slice(5,7)),year=Number(today.slice(0,4));const last=new Date(Date.UTC(year,month,0)).getUTCDate();return {from,to:`${today.slice(0,8)}${String(last).padStart(2,'0')}`};}
function downloadJson(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function ResetDataPanel({onReload}){
 const [scope,setScope]=useState('appointments'),[period,setPeriod]=useState('today'),[preview,setPreview]=useState(null),[confirm,setConfirm]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[done,setDone]=useState('');
 const range=resetRange(period),args={p_scope:scope,p_from:range.from,p_to:range.to};
 async function prepare(){setBusy(true);setError('');setDone('');try{setPreview(await rpc('spa_reset_preview',args));setConfirm('');}catch(e){setError(errorText(e));}finally{setBusy(false);}}
 async function execute(save){if(confirm!=='RESET')return;setBusy(true);setError('');try{if(save){const backup=await rpc('spa_backup_export',args);downloadJson(`ROU-SPA-backup-${scope}-${range.from||'all'}-${range.to||'all'}.json`,backup);}await rpc('spa_reset_business_data',{...args,p_confirmation:'RESET'});setPreview(null);setConfirm('');setDone('重設完成，營運統計已重新計算。');await onReload();}catch(e){setError(errorText(e));}finally{setBusy(false);}}
 return <section className="card os-danger-zone"><div className="os-page-title"><div><p className="eyebrow">OWNER CONTROL</p><h2>資料重設</h2><p className="muted">先選擇業務範圍與期間。有關聯的資料會作為一個完整鏈條重設，避免留下錯誤餘額或孤立記錄。</p></div></div><div className="form-grid"><Field label="重設內容"><select value={scope} onChange={e=>{setScope(e.target.value);setPreview(null);}}>{Object.entries(resetScopes).map(([id,[label]])=><option value={id} key={id}>{label}</option>)}</select></Field><Field label="日期範圍"><select value={period} onChange={e=>{setPeriod(e.target.value);setPreview(null);}}><option value="today">今天</option><option value="week">這個星期</option><option value="month">這個月</option><option value="all">全部期間</option></select></Field></div><p>{resetScopes[scope][1]}</p><p className="muted">範圍：{range.from?`${range.from} ～ ${range.to}`:'全部期間'}。會員檔案與儲值／套票購買記錄、員工與帳號、療程商品、庫存主資料、門店設定會保留；與被重設預約關聯的扣用會同步回復。</p><button className="danger" disabled={busy} onClick={prepare}>{busy?'檢查中…':'檢查重設範圍'}</button>{done&&<p className="success" role="status">{done}</p>}{error&&<p className="alert" role="alert">{error}</p>}{preview&&<Modal title="確認資料重設" onClose={()=>setPreview(null)}><p className="alert">這是不可復原的刪除操作。請選擇是否先下載 JSON 備份。</p><div className="os-reset-counts">{Object.entries(preview.counts).filter(([,n])=>Number(n)>0).map(([key,n])=><div key={key}><span>{({appointments:'預約',orders:'訂單',reviews:'評價',feedback:'匿名建議',payroll_runs:'薪資結算',time_entries:'工時／加班／調整',expenses:'支出'})[key]||key}</span><strong>{n}</strong></div>)}{!Object.values(preview.counts).some(Number)&&<Empty>此範圍沒有可重設記錄。</Empty>}</div><Field label="輸入 RESET 確認"><input autoComplete="off" value={confirm} onChange={e=>setConfirm(e.target.value)} placeholder="RESET"/></Field><div className="actions"><button className="primary" type="button" disabled={busy||confirm!=='RESET'} onClick={()=>execute(true)}>先儲存備份，再重設</button><button className="danger" type="button" disabled={busy||confirm!=='RESET'} onClick={()=>execute(false)}>不儲存，直接重設</button></div>{error&&<p className="alert" role="alert">{error}</p>}</Modal>}</section>;
}

function JsonSettingForm({settingKey,value,fields,saved}){const [f,setF]=useState(value);return <MutationForm action={()=>rpc('spa_business_setting_save',{p_key:settingKey,p_value:f})} onSaved={saved}>{fields.map(([key,label])=><Field key={key} label={label}><input required value={f[key]||''} onChange={e=>setF({...f,[key]:e.target.value})}/></Field>)}</MutationForm>}
function WebsiteSettingForm({value,saved}){const [f,setF]=useState(value);return <MutationForm action={()=>rpc('spa_business_setting_save',{p_key:'website',p_value:f})} onSaved={saved}><Field label="LINE 網址"><input type="url" value={f.line_url||''} onChange={e=>setF({...f,line_url:e.target.value})}/></Field>{[['booking_cta','顯示預約按鈕'],['show_staff','顯示人員'],['show_products','顯示商品']].map(([key,label])=><label className="row" key={key}><input type="checkbox" checked={!!f[key]} onChange={e=>setF({...f,[key]:e.target.checked})}/>{label}</label>)}</MutationForm>}
function InventorySettingForm({value,saved}){const [behavior,setBehavior]=useState(value.zero_stock_behavior||'sold_out');return <MutationForm action={()=>rpc('spa_business_setting_save',{p_key:'inventory',p_value:{...value,zero_stock_behavior:behavior}})} onSaved={saved}><Field label="零庫存商品"><select value={behavior} onChange={e=>setBehavior(e.target.value)}><option value="sold_out">保留並標示售罄</option><option value="hide">自動隱藏</option></select></Field></MutationForm>}
function BookingSettingForm({value,saved}){const [days,setDays]=useState(value.booking_days),[auto,setAuto]=useState(value.auto_confirm),[cancel,setCancel]=useState(value.cancellation_hours);return <MutationForm action={()=>rpc('spa_settings_save',{p_open:Number(value.opening_minute),p_close:Number(value.closing_minute),p_days:Number(days),p_auto:auto,p_cancel:Number(cancel)})} onSaved={saved}><Field label="可預約天數"><input type="number" min="1" max="365" value={days} onChange={e=>setDays(e.target.value)}/></Field><Field label="預約確認"><select value={String(auto)} onChange={e=>setAuto(e.target.value==='true')}><option value="true">自動確認</option><option value="false">人工確認</option></select></Field><Field label="取消期限（小時）"><input type="number" min="0" max="720" value={cancel} onChange={e=>setCancel(e.target.value)}/></Field></MutationForm>}
function ResourceForm({row,saved}){const [name,setName]=useState(row?.name||''),[active,setActive]=useState(row?.active??true);return <MutationForm action={()=>rpc('spa_room_save',{p_id:row?.id||null,p_name:name,p_active:active})} onSaved={saved}><Field label="床位名稱"><input required value={name} onChange={e=>setName(e.target.value)}/></Field><Field label="狀態"><select value={String(active)} onChange={e=>setActive(e.target.value==='true')}><option value="true">啟用</option><option value="false">停用</option></select></Field></MutationForm>}

export function PosOS({catalog,customers,onReload}){
 const [section,setSection]=useState('all'),[query,setQuery]=useState(''),[cart,setCart]=useState([]),[customer,setCustomer]=useState(''),[method,setMethod]=useState('cash'),[discount,setDiscount]=useState('0'),[note,setNote]=useState(''),[done,setDone]=useState('');
 const products=catalog.products.filter(x=>x.status==='active'&&Number(x.inventory)>0).map(x=>({...x,item_type:'product',key:`product:${x.id}`}));
 const services=catalog.services.filter(x=>x.status==='active').map(x=>({...x,item_type:'service',key:`service:${x.id}`}));
 const items=[...(section!=='services'?products:[]),...(section!=='products'?services:[])].filter(x=>`${x.name} ${x.sku||x.code||''}`.toLowerCase().includes(query.toLowerCase()));
 const eligibleStaff=item=>catalog.staff.filter(s=>item.item_type==='product'||catalog.skills.some(sk=>sk.staff_id===s.id&&sk.service_id===item.id));
 const add=item=>setCart(rows=>{const found=rows.find(x=>x.key===item.key);const limit=item.item_type==='product'?Number(item.inventory):99;return found?rows.map(x=>x.key===item.key?{...x,quantity:Math.min(limit,x.quantity+1)}:x):[...rows,{...item,quantity:1,staff_id:item.item_type==='service'?(eligibleStaff(item)[0]?.id||''):''}];});
 const total=cart.reduce((n,x)=>n+Number(x.price_cents)*x.quantity,0)-cents(discount||0);
 const invalidService=cart.some(x=>x.item_type==='service'&&!x.staff_id);
 const changeQty=(key,delta)=>setCart(rows=>rows.map(x=>{if(x.key!==key)return x;const limit=x.item_type==='product'?Number(x.inventory):99;return {...x,quantity:Math.max(1,Math.min(limit,x.quantity+delta))};}));
 return <><div className="os-page-title"><div><h2>門店 POS</h2><p className="muted">可同單銷售服務與商品；價格取自目錄，服務提成歸實際技師，商品提成歸指定銷售人員。</p></div></div>{done&&<p className="success" role="status">完成收款：{done}</p>}<div className="toolbar"><nav><button className={section==='all'?'active':''} onClick={()=>setSection('all')}>全部</button><button className={section==='services'?'active':''} onClick={()=>setSection('services')}>服務</button><button className={section==='products'?'active':''} onClick={()=>setSection('products')}>商品</button></nav><input aria-label="搜尋 POS 項目" placeholder="搜尋服務、商品、代碼或 SKU" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="split os-pos"><section>{!items.length&&<Empty>沒有可銷售項目。</Empty>}<div className="grid">{items.map(item=><button className="card os-product-button" key={item.key} onClick={()=>add(item)}><span className="badge">{item.item_type==='service'?'服務':'商品'}</span><strong>{item.name}</strong><span>{money(item.price_cents)}</span><small>{item.item_type==='service'?`${item.duration_minutes} 分鐘 · 可選 ${eligibleStaff(item).length} 位技師`:`庫存 ${item.inventory} ${item.unit_label||'件'}`}</small></button>)}</div></section><section className="card"><h2>本次銷售</h2>{!cart.length&&<Empty>點選左側服務或商品加入銷售。</Empty>}{cart.map(item=><div className="os-cart-row os-cart-item" key={item.key}><span><span className="badge">{item.item_type==='service'?'服務':'商品'}</span> {item.name}<small>{money(item.price_cents)} × {item.quantity}</small></span><div className="row"><button onClick={()=>changeQty(item.key,-1)}>−</button><button onClick={()=>changeQty(item.key,1)}>＋</button><button onClick={()=>setCart(rows=>rows.filter(x=>x.key!==item.key))}>移除</button></div><Field label={item.item_type==='service'?'實際服務技師（必選）':'銷售人員／商品提成（可不選）'}><select required={item.item_type==='service'} value={item.staff_id} onChange={e=>setCart(rows=>rows.map(x=>x.key===item.key?{...x,staff_id:e.target.value}:x))}><option value="">{item.item_type==='service'?'請選技師':'不指定'}</option>{eligibleStaff(item).map(s=><option key={s.id} value={s.id}>{s.name} · {s.job_title_name}</option>)}</select></Field></div>)}<Field label="會員（可不選）"><select value={customer} onChange={e=>setCustomer(e.target.value)}><option value="">散客</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name} · {c.phone}</option>)}</select></Field><Field label="折扣 NT$（元）"><input type="number" min="0" step="0.01" value={discount} onChange={e=>setDiscount(e.target.value)}/></Field><Field label="收款方式"><select value={method} onChange={e=>setMethod(e.target.value)}><option value="cash">現金</option><option value="card">刷卡</option><option value="transfer">轉帳</option></select></Field><Field label="備註"><textarea value={note} onChange={e=>setNote(e.target.value)}/></Field><div className="metric">應收 {money(Math.max(0,total))}</div>{invalidService&&<p className="alert">每個服務項目都必須指定實際服務技師。</p>}<button className="primary" disabled={!cart.length||total<0||invalidService} onClick={async()=>{const sale=await rpc('spa_pos_checkout',{p_request:crypto.randomUUID(),p_customer:customer||null,p_items:cart.map(x=>({item_type:x.item_type,item_id:x.id,quantity:x.quantity,staff_id:x.staff_id||null})),p_discount:cents(discount||0),p_method:method,p_note:note});setDone(`${sale.reference} · ${money(sale.total_cents)}`);setCart([]);setDiscount('0');setNote('');await onReload();}}>確認收款</button></section></div></>;
}
